<?php
namespace App\Services\Football;use App\Models\MarketAnalysis;final class PerformanceCalibrationService{public function report(int $days=90):array{$groups=MarketAnalysis::whereNotNull('result')->where('graded_at','>=',now()->subDays($days))->get()->groupBy(fn($a)=>$a->market_type.'|'.(int)(floor($a->score/5)*5));return $groups->map(function($items,$key){[$market,$floor]=explode('|',$key);$n=$items->count();$won=$items->where('result','won')->count();return['market'=>$market,'score_band'=>$floor.'-'.min(100,(int)$floor+4),'samples'=>$n,'won'=>$won,'lost'=>$items->where('result','lost')->count(),'observed_rate'=>$n?round($won/$n*100,1):0,'sample_status'=>$n>=50?'usable':'insufficient'];})->sortByDesc('score_band')->values()->all();}}
